    "rawText": "851: Evang.-Theol. Fakultät Bern.\nSitzungsprotokolle 3.11 - 1.12.1888:\nNachdem Schlatter im Juli 1888 einem Ruf\nauf eine ordentliche Professur für Neues\nTestament in Greifswald gefolgt ist, lehnt\ndie Fakultät die von Professor Hermann\nCremer, Greifswald, beantragte, von Professor\nSamuel Oettli, Bern, unterstützte Verleihung\ndes Dr. theol. h.c. an Adolf Schlatter nach\neingehenden Beratungen ab.\nBei weiteren Beratungen über Petitionen des\nEvang.-theol. Vereins und des Evang.-kirchlichen\nVereins Bern zur Frage der Nachfolge Schlatters\nwird u.a. eine künftige Privatdozentur für Lic.\ntheol. Friedrich Barth, Basel, nicht ausge-\nschlossen.\nZugangsbsuch Nr. 107 b",
