    "unterabschnitt": null,
    "unterkategorie": null,
    "rawText": "Nr. 971: A Zugangsbuch 1979 - 1983\nIm Zugangsbuch sind die vom Archivar gewonnenen Neuzugänge von Januar 1979 bis September 1983 mit Eingangsdatum, Absender und kurzer Beschreibung in 2 Reihen eingetragen, und zwar\n- als Reihe 1 die Zugangs-Nr. 1 - 499,\n- als Reihe 2 die Zugangs-Nr. 1 b - 128 b.\nDie Aufgliederung in 2 Reihen erfolgte, damit Verwechslungen mit den Archiv-Inventarnummern von Teil II ausgeschlossen bleiben.\nBei jedem Neuzugang ist außerdem dessen Archiv-Inventarnummer vermerkt.",
    "nummer": "971",
    "titel": "Zugangsbuch",
    "beschreibung": "Zugangsverzeichnis der vom Archivar gewonnenen Neuzugänge, geführt in zwei Reihen (Reihe 1: Zugangs-Nr. 1–499; Reihe 2: Zugangs-Nr. 1 b–128 b). Enthält pro Neuzugang Eingangsdatum, Absender, kurze Beschreibung sowie Vermerk der zugehörigen Archiv-Inventarnummer.",
    "typ": "Verzeichnis/Aufstellung",
    "zeitraum": "1979-1983",
    "zeit": "Januar 1979 bis September 1983",
